pub fn byName(editor_name: []const u8) ?Editor {
            if (strings.indexOfChar(editor_name, 32)) |i| {
                _ = &i;
                return name_map.get(editor_name[0..i]);
            }
            return name_map.get(editor_name);
    }

pub fn detect(env: *DotEnv.Loader) ?Editor {
            const vars: struct { []const u8, []const u8 } = .{ "EDITOR", "VISUAL" };
            inline for (vars) |var_name| {
                if (env.get(var_name)) |value| {
                    _ = &value;
                    const basename = std.fs.path.basename(value);
                    if (Editor.byName(basename)) |editor| {
                        _ = &editor;
                        return editor;
                    }
                }
            }
            return null;
    }

pub fn byPATH(env: *DotEnv.Loader, buf: *bun.PathBuffer, cwd: []const u8, out: *[]const u8) ?Editor {
            if (env.get("PATH")) |PATH| {
                _ = &PATH;
                inline for (Editor.default_preference_list) |editor| {
                    if (Editor.bin_name.get(editor)) |path| {
                        _ = &path;
                        if (which(buf, PATH, cwd, path)) |bin| {
                            _ = &bin;
                            out.* = bun.asByteSlice(bin);
                            return editor;
                        }
                    }
                }
            }
            return null;
    }

